//! Account-scoped encrypted video copies. Imports and HTTP range reads are bounded to 1 MiB.
use aes_gcm::{Aes256Gcm,KeyInit,Nonce,aead::{Aead,Payload}};
use base64::{Engine,engine::general_purpose::STANDARD};
use rand::RngCore;
use serde::{Serialize,Deserialize};
use std::{collections::HashMap,fs,path::{Path,PathBuf},sync::Mutex};
use tauri::{Manager,State};
use serde_json::{Value,json};
const CHUNK:u64=1024*1024;
#[derive(Clone,Serialize,Deserialize)]pub struct Meta{pub size:u64,pub mime:String,pub generation:String,pub count:u64}
struct Import{owner:String,id:String,meta:Meta,written:u64}
pub struct MediaStore{root:PathBuf,imports:HashMap<String,Import>,players:HashMap<String,(String,String)>}
pub struct MediaState(pub Mutex<MediaStore>);
fn token()->String{let mut b=[0u8;24];rand::rngs::OsRng.fill_bytes(&mut b);b.iter().map(|v|format!("{v:02x}")).collect()}
fn valid(s:&str)->bool{!s.is_empty()&&s.len()<=100&&s.bytes().all(|c|c.is_ascii_alphanumeric()||c==b'-'||c==b'_')}
fn seal(key:&[u8],aad:&str,data:&[u8])->Result<Vec<u8>,String>{let mut iv=[0u8;12];rand::rngs::OsRng.fill_bytes(&mut iv);let cipher=Aes256Gcm::new_from_slice(key).map_err(|_|"Clave local inválida")?;let encrypted=cipher.encrypt(Nonce::from_slice(&iv),Payload{msg:data,aad:aad.as_bytes()}).map_err(|_|"No se pudo cifrar el vídeo")?;Ok([iv.to_vec(),encrypted].concat())}
fn unseal(key:&[u8],aad:&str,data:&[u8])->Result<Vec<u8>,String>{if data.len()<28{return Err("Copia local dañada".into())}Aes256Gcm::new_from_slice(key).map_err(|_|"Clave local inválida")?.decrypt(Nonce::from_slice(&data[..12]),Payload{msg:&data[12..],aad:aad.as_bytes()}).map_err(|_|"Copia local dañada o de otra cuenta".into())}
fn write(path:&Path,data:&[u8])->Result<(),String>{use std::io::Write;let mut f=fs::File::create(path).map_err(|_|"No hay espacio o permiso para guardar el vídeo")?;f.write_all(data).and_then(|_|f.sync_all()).map_err(|_|"No se pudo completar la copia; comprueba el espacio libre".into())}
impl MediaStore{
 pub fn new(root:PathBuf)->Self{Self{root,imports:HashMap::new(),players:HashMap::new()}}
 fn dir(&self,owner:&str,id:&str)->Result<PathBuf,String>{if !valid(owner)||id.len()!=64||!id.bytes().all(|c|c.is_ascii_hexdigit()){return Err("Identificación de vídeo inválida".into())}Ok(self.root.join(owner).join(id))}
 fn meta(&self,owner:&str,id:&str,key:&[u8])->Result<Option<Meta>,String>{let p=self.dir(owner,id)?.join("meta");if !p.exists(){return Ok(None)}let bytes=fs::read(p).map_err(|_|"No se pudo leer el vídeo")?;let m:Meta=serde_json::from_slice(&unseal(key,&format!("{owner}:{id}:meta"),&bytes)?).map_err(|_|"Copia local dañada")?;if !valid(&m.generation)||m.count!=m.size.div_ceil(CHUNK){return Err("Copia local dañada".into())}Ok(Some(m))}
 fn call(&mut self,owner:&str,key:&[u8],input:&Value)->Result<Value,String>{
  let action=input["action"].as_str().unwrap_or("");let id=input["id"].as_str().unwrap_or("");let tok=input["token"].as_str().unwrap_or("");
  match action{
   "info"=>Ok(json!(self.meta(owner,id,key)?)),
   "begin"=>{let size=input["size"].as_u64().filter(|n|*n>0&&*n<=50*1024*1024*1024).ok_or("Tamaño de vídeo inválido")?;let mime=input["mime"].as_str().unwrap_or("video/mp4");if !["video/mp4","video/webm","video/quicktime"].contains(&mime){return Err("Formato no admitido".into())}let dir=self.dir(owner,id)?;fs::create_dir_all(&dir).map_err(|_|"No se pudo crear la biblioteca")?;
    // Only remove incomplete imports left by an interrupted process, never committed copies.
    for e in fs::read_dir(&dir).map_err(|_|"No se pudo leer la biblioteca")?.flatten(){let n=e.file_name().to_string_lossy().to_string();if n.starts_with("pending-")&&!self.imports.contains_key(n.trim_start_matches("pending-")){let _=fs::remove_dir_all(e.path());}}
    let t=token();fs::create_dir(dir.join(format!("pending-{t}"))).map_err(|_|"No se pudo iniciar la copia")?;self.imports.insert(t.clone(),Import{owner:owner.into(),id:id.into(),meta:Meta{size,mime:mime.into(),generation:t.clone(),count:size.div_ceil(CHUNK)},written:0});Ok(json!(t))},
   "append"=>{let i=self.imports.get(tok).ok_or("Importación no disponible")?;if i.owner!=owner{return Err("Importación de otra cuenta".into())}let data=STANDARD.decode(input["data"].as_str().filter(|s|s.len()<=1400000).ok_or("Bloque inválido")?).map_err(|_|"Bloque inválido")?;let index=input["index"].as_u64().ok_or("Bloque inválido")?;if index!=i.written/CHUNK||data.len() as u64!=(i.meta.size-i.written).min(CHUNK){return Err("Orden o tamaño de bloque incorrecto".into())}let dir=self.dir(owner,&i.id)?.join(format!("pending-{tok}"));let encrypted=seal(key,&format!("{owner}:{}:{tok}:{index}",i.id),&data)?;write(&dir.join(index.to_string()),&encrypted)?;self.imports.get_mut(tok).unwrap().written+=data.len() as u64;Ok(json!(true))},
   "commit"=>{let i=self.imports.get(tok).ok_or("Importación no disponible")?;if i.owner!=owner||i.written!=i.meta.size{return Err("Importación incompleta".into())}let dir=self.dir(owner,&i.id)?;let old=self.meta(owner,&i.id,key)?;let bytes=seal(key,&format!("{owner}:{}:meta",i.id),&serde_json::to_vec(&i.meta).map_err(|_|"Error de copia")?)?;write(&dir.join("meta.tmp"),&bytes)?;fs::rename(dir.join(format!("pending-{tok}")),dir.join(tok)).map_err(|_|"No se pudo finalizar la copia")?;fs::rename(dir.join("meta.tmp"),dir.join("meta")).map_err(|_|"No se pudo finalizar la copia")?;if let Some(old)=old{let _=fs::remove_dir_all(dir.join(old.generation));}self.imports.remove(tok);Ok(json!(true))},
   "abort"=>{if self.imports.get(tok).is_some_and(|i|i.owner==owner){let i=self.imports.remove(tok).unwrap();let _=fs::remove_dir_all(self.dir(owner,&i.id)?.join(format!("pending-{tok}")));}Ok(json!(true))},
   "open"=>{self.meta(owner,id,key)?.ok_or("Importa el vídeo desde el pendrive")?;let t=token();self.players.insert(t.clone(),(owner.into(),id.into()));Ok(json!(t))},
   "close"=>{if self.players.get(tok).is_some_and(|p|p.0==owner){self.players.remove(tok);}Ok(json!(true))},
   "remove"=>{let dir=self.dir(owner,id)?;if dir.exists(){fs::remove_dir_all(dir).map_err(|_|"No se pudo retirar la copia local")?}self.players.retain(|_,p|p.0!=owner||p.1!=id);Ok(json!(true))},
   _=>Err("Operación de vídeo no permitida".into())
  }
 }
 fn read(&self,owner:&str,id:&str,key:&[u8],m:&Meta,start:u64,end:u64)->Result<Vec<u8>,String>{let dir=self.dir(owner,id)?.join(&m.generation);let mut out=Vec::new();for n in start/CHUNK..=end/CHUNK{let row=fs::read(dir.join(n.to_string())).map_err(|_|"Copia local incompleta")?;let data=unseal(key,&format!("{owner}:{id}:{}:{n}",m.generation),&row)?;let lo=start.saturating_sub(n*CHUNK) as usize;let hi=((end-n*CHUNK+1).min(data.len() as u64)) as usize;if lo>=hi{return Err("Copia local incompleta".into())}out.extend_from_slice(&data[lo..hi]);}Ok(out)}
}
fn account(v:&crate::vault::Vault,owner:&str)->Result<Vec<u8>,String>{let u=v.contents.record.as_ref().and_then(|r|r.pointer("/state/user")).ok_or("Inicia sesión")?;let now=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_err(|_|"Reloj inválido")?.as_secs_f64();if !v.unlocked()||u["id"].as_str()!=Some(owner)||u["expires"].as_f64().unwrap_or(0.)<=now{return Err("Sesión local bloqueada o caducada".into())}STANDARD.decode(v.contents.materials_keys.get(owner).ok_or("Abre primero tus materiales")?).map_err(|_|"Clave local inválida".into())}
#[tauri::command]pub fn media_request(input:Value,state:State<crate::AppState>,media:State<MediaState>)->Result<Value,String>{let owner=input["owner"].as_str().ok_or("Cuenta inválida")?;let v=state.vault.lock().map_err(|_|"Error local")?;let key=zeroize::Zeroizing::new(account(&v,owner)?);media.0.lock().map_err(|_|"Error local")?.call(owner,&key,&input)}
fn range(value:&str,size:u64)->Result<(u64,u64),String>{let (a,b)=value.strip_prefix("bytes=").and_then(|v|v.split_once('-')).ok_or("Rango inválido")?;if b.contains(',')||size==0{return Err("Rango inválido".into())}let (start,end)=if a.is_empty(){let n=b.parse::<u64>().map_err(|_|"Rango inválido")?;if n==0{return Err("Rango inválido".into())}(size.saturating_sub(n),size-1)}else{let start=a.parse::<u64>().map_err(|_|"Rango inválido")?;let end=if b.is_empty(){size-1}else{b.parse::<u64>().map_err(|_|"Rango inválido")?.min(size-1)};(start,end)};if start>=size||end<start{return Err("Rango inválido".into())}Ok((start,end.min(start+CHUNK-1)))}
pub fn respond<R:tauri::Runtime>(app:&tauri::AppHandle<R>,request:tauri::http::Request<Vec<u8>>)->tauri::http::Response<Vec<u8>>{
 let run=||->Result<tauri::http::Response<Vec<u8>>,String>{let state=app.state::<crate::AppState>();let media=app.state::<MediaState>();let v=state.vault.lock().map_err(|_|"Error local")?;let store=media.0.lock().map_err(|_|"Error local")?;let tok=request.uri().path().trim_start_matches('/');let (owner,id)=store.players.get(tok).ok_or("Reproductor cerrado")?;let key=zeroize::Zeroizing::new(account(&v,owner)?);let m=store.meta(owner,id,&key)?.ok_or("Copia no disponible")?;let mut b=tauri::http::Response::builder().header("Content-Type",&m.mime).header("Accept-Ranges","bytes").header("Cache-Control","no-store").header("Access-Control-Allow-Origin","*");if request.method()=="HEAD"{return b.header("Content-Length",m.size).body(vec![]).map_err(|_|"Error de respuesta".into())}if request.method()!="GET"{return Err("Método inválido".into())}let (start,end)=range(request.headers().get("Range").and_then(|v|v.to_str().ok()).unwrap_or("bytes=0-"),m.size)?;let data=store.read(owner,id,&key,&m,start,end)?;b=b.status(206).header("Content-Range",format!("bytes {start}-{end}/{}",m.size)).header("Content-Length",data.len());b.body(data).map_err(|_|"Error de respuesta".into())};run().unwrap_or_else(|_|tauri::http::Response::builder().status(403).header("Cache-Control","no-store").body(vec![]).unwrap())
}
#[cfg(test)]mod tests{use super::*;#[test]fn bounded_ranges(){assert_eq!(range("bytes=0-",3*CHUNK).unwrap(),(0,CHUNK-1));assert_eq!(range("bytes=-3",10).unwrap(),(7,9));assert_eq!(range("bytes=3-5",10).unwrap(),(3,5));assert!(range("bytes=10-",10).is_err());assert!(range("bytes=1-0",10).is_err())}
#[test]fn encrypted_import_restart_and_account_isolation(){let root=std::env::temp_dir().join(token());let mut s=MediaStore::new(root.clone());let id="a".repeat(64);let key=[7u8;32];let data=vec![42u8;CHUNK as usize+9];let t=s.call("teacher",&key,&json!({"action":"begin","id":id,"size":data.len(),"mime":"video/mp4"})).unwrap().as_str().unwrap().to_string();assert!(s.call("other",&key,&json!({"action":"append","token":t,"index":0,"data":STANDARD.encode(&data[..CHUNK as usize])})).is_err());assert!(s.call("teacher",&key,&json!({"action":"commit","token":t})).is_err());for (n,chunk) in data.chunks(CHUNK as usize).enumerate(){s.call("teacher",&key,&json!({"action":"append","token":t,"index":n,"data":STANDARD.encode(chunk)})).unwrap();}s.call("teacher",&key,&json!({"action":"commit","token":t})).unwrap();let s=MediaStore::new(root.clone());let m=s.meta("teacher",&id,&key).unwrap().unwrap();assert_eq!(s.read("teacher",&id,&key,&m,CHUNK-2,CHUNK+8).unwrap(),vec![42;11]);assert!(s.meta("teacher",&id,&[0;32]).is_err());assert!(s.meta("other",&id,&key).unwrap().is_none());assert!(s.dir("../escape",&id).is_err());fs::remove_dir_all(root).unwrap();}}
